UPDATE recipes SET ingredients = '[{"qty":"1","unit":"cup","name":"egg whites"},{"qty":"4","unit":"slices","name":"regular ass white"},{"qty":"","unit":"","name":"bread (up to 80 calories per"},{"qty":"","unit":"","name":"slice)"},{"qty":"1","unit":"packet","name":"sweetener"},{"qty":"1","unit":"tsp","name":"cinnamon"},{"qty":"1","unit":"tbsp","name":"vanilla extract"},{"qty":"0.5","unit":"cup","name":"blueberries"},{"qty":"0.5","unit":"cup","name":"low calorie syrup"}]'::jsonb, instructions = '1. In a bowl, add egg whites, sweetener, cinnamon, and vanilla extract. Whisk until spices are evenly distributed throughout the mixture.
2. Heat a griddle over low-medium heat. Spray griddle with cooking spray.
3. Dip P28 bread slices into egg white mixture, and transfer to pan.
4. Spoon any leftover egg white mixture into the bread in the pan. If done slowly, the bread should absorb the mixture and get fluffy.
5. Let cook for about 3-4 minutes on each side.
6. Remove French toast from the pan and serve on a plate with toppings. Suggestions for toppings are blueberries and low calorie syrup. (NOTE: toppings are NOT included in the estimated nutritional values).

— From Greg Doucette, "The Ultimate Anabolic Cookbook" (#CHEFGREG)' WHERE name = 'Anabolic French Toast Simple Version';
