UPDATE recipes SET ingredients = '[{"qty":"2","unit":"slices","name":"regular ass white bread (up"},{"qty":"","unit":"","name":"to 80 calories per slice)"},{"qty":"150","unit":"g","name":"strained extra lean ground"},{"qty":"","unit":"","name":"beef (96% lean)"},{"qty":"","unit":"","name":"Can of gravy (up to 50 calories)"},{"qty":"1","unit":"","name":"serving veggies (up to 100"}]'::jsonb, instructions = '1. Form a patty with the ground beef, salt and pepper (and any other seasonings to taste such as: cumin, parsley, chili flakes, etc).
