UPDATE recipes SET ingredients = '[{"qty":"2","unit":"cups","name":"0/% fat cottage cheese"},{"qty":"4.5","unit":"cups","name":"unsweetened almond milk"},{"qty":"2","unit":"scoops","name":"RYSE chocolate peanut butter cup"},{"qty":"","unit":"","name":"whey protein"},{"qty":"1","unit":"","name":"package of fat-free Jell-O chocolate"},{"qty":"","unit":"","name":"pudding (120 calories)"},{"qty":"","unit":"","name":"1.5-2 tbsp guar/xanthan gum"},{"qty":"10","unit":"","name":"packets of sweetener"},{"qty":"","unit":"","name":"Optional Substitutions"},{"qty":"2","unit":"scoops","name":"casein protein instead of RYSE"},{"qty":"","unit":"","name":"whey protein"}]'::jsonb, instructions = '1. Add all ingredients to a blender. Blend for 3 minutes on medium-high speed until there is a smooth consistency. Note that the more casein protein is used, the thicker the pudding will be.
2. Remove pudding from blender and transfer to an airtight refrigerator safe container. Pudding is ready to eat. Makes 9 servings

— From Greg Doucette, "The Ultimate Anabolic Cookbook" (#CHEFGREG)' WHERE name = 'Cottage Cheese Protein Pudding - Chocolate';
UPDATE recipes SET ingredients = '[{"qty":"1/2","unit":"cup","name":"rolled oats"},{"qty":"500","unit":"g","name":"apples"},{"qty":"6","unit":"","name":"packets sweetener"},{"qty":"3","unit":"tsp","name":"guar gum (*use certified"}]'::jsonb, instructions = '1. Chop apples into medium cubes.
2. Add apples, oats, sweetener, and cinnamon to a large microwave-safe bowl and toss with a fork.
3. Blend water and guar gum on high for 15 seconds.
4. Add blended water and guar gum mixture to the microwave-safe container, and stir all ingredients with a fork.
5. Place the bowl in the microwave and heat on high. Remove the bowl from the microwave and add water and stir as needed until apples are very soft. Vegetarian Gluten-Free Vegan Makes 4 servings Ready in: 5 min.

— From Greg Doucette, "The Ultimate Anabolic Cookbook" (#CHEFGREG)' WHERE name = 'Apple Goop';
UPDATE recipes SET ingredients = '[{"qty":"1.5","unit":"cups","name":"lactose-free protein milk (120"}]'::jsonb, instructions = '1. Add all ingredients to a blender. Blend for 3 minutes on medium-high speed until there is a smooth consistency..
2. Remove pudding from blender and transfer to an airtight refrigerator safe container. Pudding is ready to eat. Makes 2 servings Prep Time: 2 min. | Ready in: 6 min.

