UPDATE recipes SET ingredients = '[{"qty":"2","unit":"cups","name":"0% fat free cottage cheese"},{"qty":"3","unit":"cups","name":"unsweetened almond milk (90 calories)"},{"qty":"1","unit":"scoop","name":"RYSE chocolate peanut butter cup"},{"qty":"","unit":"","name":"whey protein powder"},{"qty":"24","unit":"g","name":"PB2 (or equivalent powdered peanut butter)"},{"qty":"1","unit":"packet","name":"of fat-free sugar-free Jell-O chocolate"},{"qty":"","unit":"","name":"pudding (120 calories)"},{"qty":"","unit":"","name":"1.5-2 tbsp guar/xanthan gum"},{"qty":"14","unit":"g","name":"unsweetened cocoa powder"},{"qty":"10","unit":"","name":"packets sweetener (to taste)"}]'::jsonb, instructions = '1. Add all ingredients to a blender. Blend for 3 minutes on medium-high speed until there is a smooth consistency. Note that the more casein protein is used, the thicker the pudding will be.
