UPDATE recipes SET ingredients = '[{"qty":"1","unit":"scoop","name":"whey protein"},{"qty":"100-150","unit":"g","name":"frozen strawberries or berries"},{"qty":"1/2","unit":"cup","name":"unsweetened almond milk or 0% Greek yogurt"},{"qty":"1","unit":"packet","name":"sweetener"}]'::jsonb, instructions = '1. Blend whey, frozen fruit, milk, sweetener until smooth.
