— From Greg Doucette, "The Ultimate Anabolic Cookbook" (#CHEFGREG)' WHERE name = 'Strawberry Cheesecake Proteinsicles';
UPDATE recipes SET ingredients = '[{"qty":"1-2","unit":"scoop","name":"whey or casein protein"},{"qty":"100-200","unit":"g","name":"frozen fruit (berries / strawberries / blueberries)"},{"qty":"1/3-2/3","unit":"cup","name":"unsweetened almond milk"},{"qty":"1","unit":"tsp","name":"guar/xanthan gum"},{"qty":"1-2","unit":"packets","name":"sweetener"},{"qty":"","unit":"","name":"Ice"}]'::jsonb, instructions = '1. Add ice to a blender first to chill the mixture.
2. Add the whey/casein/protein powder, frozen fruit, almond milk (or water), sweetener, and guar/xanthan gum.
3. Blend on high until smooth and thick. For a "pudding" texture, add 0.5 cup 0% Greek yogurt and blend less.
4. Pour into a glass or bowl. Top with optional sugar-free syrup or PB2 drizzle.

